<?php
namespace Core;require_once __DIR__.'/Guard.php';ml_guard_shield(__FILE__);class Http{public static function get($a,array $b=[],$c=3){$d=0;$e=1;while($d<$c){$d++;$f=curl_init($a);curl_setopt_array($f,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>20,CURLOPT_CONNECTTIMEOUT=>10,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_HTTPHEADER=>$b,CURLOPT_USERAGENT=>'MediaLibraryAPI/1.0',]);$g=curl_exec($f);$h=(int)curl_getinfo($f,CURLINFO_HTTP_CODE);$i=curl_error($f);curl_close($f);if($g===false){if($d<$c){sleep($e);$e=min($e*2,8);continue;}throw new \RuntimeException("HTTP request failed: $i ($a)");}if($h===429){if($d<$c){sleep($e);$e=min($e*2,8);continue;}}$j=json_decode($g,true);if(!is_array($j)){if($d<$c){sleep($e);$e=min($e*2,8);continue;}throw new \RuntimeException("Invalid JSON from $a");}return['code'=>$h,'data'=>$j];}throw new \RuntimeException("HTTP request failed after retries: $a");}}